UPDATE campus_public_web_whitelist
site_name = #{siteName}, site_domain = #{siteDomain}, base_url = #{baseUrl}, allowed_path_prefix = #{allowedPathPrefix}, authorization_basis = #{authorizationBasis}, authorization_scope = #{authorizationScope}, robots_policy = #{robotsPolicy}, rate_limit_seconds = #{rateLimitSeconds}, max_depth = #{maxDepth}, responsible_department_id = #{responsibleDepartmentId}, enabled = #{enabled}, remark = #{remark}, update_user_id = #{updateUserId}
WHERE whitelist_id = #{whitelistId} AND deleted = 0

